// Package Library (redesigned Install Package screen — DPI-only)
"pkglib.install": "Install",
"pkglib.reinstall": "Reinstall",
"pkglib.retry_stream": "Retry with Stream",
"pkglib.retry_stream_hint": "Send this package from the PS5's own storage through Stream instead. The PS5 refused it the other way (0x80b2116f); the package is not copied again.",
