"pkglib.section.dlc": "DLC",
"pkglib.variant.select": "Include in Install all (this PS5)",
"pkglib.variant.selected": "Included in Install all (this PS5)",
"pkglib.variant.help": "When several packages are the same game update or DLC, pick exactly one for the bulk Install all button. Uncheck to leave it out. Single Install on the row always installs this package only.",
// Stated, not detected: no header field separates a fake package from a
// retail one (every candidate marker is present on genuine Sony packages
// too), so the screen names the prerequisite and lets the reader decide.
"pkglib.fpkgsupport.title": "Installing a fake package (FPKG)?",
"pkglib.fpkgsupport.lead": "A PS5 fake package only installs when fake-package support is already loaded on the console. Load all three, in this order, before installing:",
"pkglib.fpkgsupport.kstuff": "— the build with PS5 fake-package support",
"pkglib.fpkgsupport.ppr": "— applies the PPR plaintext / no-auth patch",
"pkglib.fpkgsupport.ppr_where": "No download is published for it: it is built from the source on GitHub,",
"pkglib.fpkgsupport.smp": "— the mount layer that registers the installed title",
"pkglib.fpkgsupport.tail": "Without them the console refuses the install, or takes it and then fails to mount the game. Retail and debug packages need none of this — if that is what you are installing, ignore this note.",
"pkglib.installnote.title": "How installing works",
"pkglib.installnote.body": "ps5upload hands the package to its own installer on the PS5 and only reports it installed once the console has read the whole package; a patch must also raise the game's version. If an install fails, the package is kept so you can retry. FW 12+ and system packages may still require the PS5's own Settings → System → Debug Settings → Game → Package Installer.",
"pkglib.error": "Something went wrong",
"pkglib.refreshDeferred": "The package list refreshes when the install that is running ends.",
"pkglib.delete.confirmTitle": "Delete {name}?",
"pkglib.delete.confirmBody": "This permanently removes the uploaded .pkg ({size}) from your PS5. Any already-installed copy of the game stays installed; you'd just need to re-upload the .pkg to install it again.",
"pkglib.footer.count": "{n} packages",
"pkglib.footer.size": "{size} on PS5",
"pkglib.clearFinished": "Clear finished ({n})",
"pkglib.installAll": "Install all",
"pkglib.installAll.hint": "Install every staged package, base games before updates and DLC",
"pkglib.installAll.what": "What is Install all?",
"pkglib.installAll.whatBody": "Install all runs every ready package in order: base game → updates → DLC. When you have two updates of the same version (or two DLC packs that conflict), use the checkbox on each row to choose which one this console should install — only one per group. Uncheck to leave that group out. The Install button on a single row always installs just that package.",
"pkglib.clearAll": "Clear all",
"pkglib.clearAll.confirmTitle": "Delete all staged packages?",
"pkglib.clearAll.confirmBody": "This permanently deletes all {n} staged .pkg file(s) from the PS5. Installed games are not affected.",
"pkglib.autoRemove": "Auto-delete each package from the PS5 after it installs",
"pkglib.autoInstall": "Install automatically once the upload finishes",
