"fpkg.installedTitle": "Installed on PS5 \u2014 {title}",
"fpkg.ratio": "({pct}% of {size})",
"fpkg.launchUnknown": "Cannot tell which title to launch; start it from the PS5.",
"fpkg.aboutTitle": "About converting",
"fpkg.card.run": "\u2462 Build & install",
"pkg.reason.loader_unreachable": "The PS5's payload loader wasn't reachable \u2014 reload it and retry.",
"pkg.reason.no_bringup": "The install daemon couldn't be brought up on the PS5.",
"pkg.reason.no_image": "This build has no bundled installer daemon image.",
"pkg.reason.source_gone": "The package source was no longer available when the install ran.",
"pkg.reason.destructive_guard": "This would erase the installed game first; re-run allowing a destructive re-install.",
"pkg.reason.bad_request": "The installer rejected the request.",
"pkg.reason.sony_refused": "The PS5 declined the install.",
"pkg.sony_80b21104": "The PS5 would not accept this package (0x80B21104). When other packages install on this console, it is this file: most often a recent game whose package was made with tools newer than this console's firmware understands, or a package that is not a fake-signed (FPKG) build. Use a package made for your firmware (a backport), or install the game another way that skips the installer: copy its game folder, or a game image (.exfat or .ffpfsc) for ShadowMount+, with Upload.",
"pkg.reason.stalled": "The PS5 stopped fetching the package before it finished. The package was kept \u2014 try again.",
"pkg.reason.stream_unreachable": "The PS5 never reached this computer to fetch the package. Allow ps5upload through this computer's firewall (on Windows, for both Private and Public networks), keep the computer and the PS5 on the same network with any VPN off, and set the PS5's Proxy Server to \u201cDo Not Use\u201d. Upload & install works without this connection.",
"pkg.reason.staged_refused": "The PS5 refused this package from its own storage. A bug in ps5upload caused this before 6.3.1 and is fixed, so it should no longer happen; it is not a problem with the file. If you see it again, install it with Stream & install from a computer (the desktop app, or the web UI on a home server) and send us a bug report.",
"pkg.reason.stream_proxy": "The PS5's proxy setting blocked the stream. In the PS5's network Advanced Settings set Proxy Server to \u201cDo Not Use\u201d, or use Upload & install, which reads the package from PS5-local storage.",
