library_mount_modal_cross_volume: "Heads-up: image lives on {imageVolume} but you picked {volume}. Some PS5 firmwares refuse cross-volume nmount with EPERM (the kernel won't mount a file from one drive into a path on another). If the mount fails, retry with {imageVolume} as the volume.",
library_mount_modal_read_only: "Mount read-only",
library_mount_modal_read_only_hint: "— safest, and right for shared dumps or save-data PFS images. Leave it OFF to edit the image: replace files, add DLC, or apply a backport patch. Requires payload 2.2.26+.",
library_mount_modal_usb_warn_body: "/mnt/usb* and /mnt/ext* belong to the PS5 kernel's USB hotplug namespace; mounting an image there is blocked by kernel policy on most firmware. If this fails with \"Operation not permitted\", switch to /mnt/ps5upload (the payload's private mount root) or /data — both work without kernel patches.",
