payloads_essentials_title: "Recommended alongside ps5upload",
payloads_essentials_body: "If you are setting up a console for the first time, these three cover most of what ps5upload expects to find: kstuff-lite (kernel patches most homebrew relies on), ShadowMount+ (mount game images from storage) and nanoDNS (keep the console off Sony's update path). Everything else in this list is optional.",
