auto_bringup_label: "Bring up automatically",
auto_bringup_hint: "When a saved PS5's loader (elfldr, port 9021) is up and the helper isn't running, the app runs Quick bring-up by itself: your bring-up playlist if you set one, then the helper, then your auto-loader playlist. Once each time the console starts; after rest mode only the helper is sent again. It waits about 90 seconds after the loader appears, so the console's own autoloader can finish first. Off by default.",
