bandwidth_cap_clear: "remove limit",
reset_hint_v2: "Wipe every local trace of PS5Upload and start over: settings, saved PS5s and their pairings, the Collection, saved servers and their passwords, backport libraries, install history, jobs and events, activity/queue history, logs, payload caches, and crash reports. Nothing on your PS5 is affected. Backup / restore above does not cover pairings, the Collection, server passwords or backport libraries.",
reset_hint_browser: "Clear every setting and saved state this browser keeps for PS5Upload and start over. What the engine keeps on its server (console pairings, the Collection, saved servers, backport libraries, install history, logs) is not touched, and nothing on your PS5 is affected.",
