keep_awake_mode_always: "Always while connected",
keep_ps5_awake_mode_hint_v2: "Periodically resets the PS5's auto-standby timer so it can't drop into rest mode. “During uploads and installs” protects long uploads (a common cause of failed uploads; default). “Always while connected” keeps every console with a running helper out of rest mode for as long as the app is open. Putting the PS5 to rest manually still works in every mode.",
upload_auto_redeploy_on_wake: "Reconnect automatically after rest mode / network drops",
upload_auto_redeploy_on_wake_hint: "When the PS5's helper goes offline (rest mode, a WiFi switch, or a payload crash), keep trying to re-send it in the background — so the helper, your fan threshold, and the upload port come back by themselves once the console is reachable again, without clicking Connect. On by default.",
upload_system_file_read: "Allow downloading system files (/system, /system_data)",
upload_system_file_read_hint: "Lets the FileSystem browser download files from read-only system partitions that are normally blocked (e.g. /system/common/lib, /system_data/priv). Read-only — never affects delete, move, or write. Off by default; turn on only if you know what you're doing.",
upload_register_after_title: "Add to PS5 home screen when done",
upload_register_after_desc: "Registers the game with the PS5 right after the upload finishes, so it's ready to launch. If this step fails the upload itself is unaffected and you can still register it from the game's page in Games.",
upload_done_next_hint2: "Next: open the game in Games and, under On the PS5's drives, add it to the home screen or mount it.",
upload_done_open_drives: "Open in Games",

