helper_mismatch_title: "The PS5 helper is v{payload} but this app is v{app}",
helper_mismatch_send: "Send helper",
helper_mismatch_body_v3: "Nothing to do on the PS5 itself: press Send helper and this app sends the matching helper to the console. Fixes and features from the newer version won't work until then.",

"joberr.direct_staged_file_missing": "This upload had already finished, so there was nothing left to publish — and the file on the PS5 is now missing or the wrong size. Upload it again and choose Override rather than Resume.",
"joberr.direct_tx_corrupt": "The PS5 detected protocol corruption on this transfer. Restart the payload from the Send Payload tab and retry.",
"joberr.direct_writer_io_error": "The PS5 ran out of free space (or an external drive disconnected) while writing the file. Free up space on the destination drive and click Retry — the upload resumes from where it stopped.",
"joberr.fs_delete_path_not_allowed": "PS5 refused access to that path. Use /data/, /user/, or a mounted /mnt/ext*, /mnt/usb* path.",
"joberr.fs_read_path_not_allowed": "This file is in a read-only system partition that's normally blocked. Enable Settings → \"Allow downloading system files\" to download from /system, /system_data, and other protected paths.",
"joberr.fs_write_failed": "The PS5 couldn't write to the destination mid-transfer — most often the drive filled up or an external drive disconnected. Check free space / reconnect the drive, then click Retry (the upload resumes from where it stopped).",
"joberr.fs_write_failed_no_space": "The destination drive ran out of space (or the file is too big for that filesystem). Free space on the PS5 / external drive — or pick a different destination — then click Retry.",
"joberr.packed_unsupported": "The PS5 helper rejected a packed transfer — this happens with an outdated payload when a folder upload comes down to a single small file (e.g. a Resume of a game with many tiny files). Update ps5upload to the latest version, re-send the payload from the Send Payload tab, then retry.",
"joberr.preflight_insufficient_space": "The destination drive doesn't have enough free space for this file. Free up space on the PS5 (Settings → Storage) or pick a different destination, then click Retry.",
"joberr.size_mismatch": "The transfer didn't finish before being interrupted — a file on the PS5 is incomplete, so it wasn't published (your old copy, if any, is untouched). This usually means the PS5 went into rest mode or lost power mid-upload. Keep the console awake (Settings → System → Power Saving → Set Time Until PS5 Turns Off), then re-run this item — Resume now re-sends only the missing files, or choose Override for a clean copy.",
"joberr.ava1_stalled": "The transfer stopped making progress (the source stopped sending data). Retry; if it repeats, check the source drive or network share.",
"joberr.tx_table_full": "Too many simultaneous transfers in flight on the PS5. Wait for some to finish or restart the payload.",
"joberr.zip_unsupported": "This .zip uses something the uploader can't stream (encryption, a compression method other than Deflate or Stored, or an unsafe or duplicate file path). Extract it on your computer and upload the folder instead.",
"joberr.sevenz_unsupported": "This .7z uses a compression method or feature the uploader can't stream. Extract it on your computer and upload the folder instead.",
"joberr.sevenz_unsupported_layout": "This .7z keeps directories or empty files between its files inside one solid block, a layout the uploader can't stream. Re-pack it with 7-Zip, or extract it and upload the folder.",
"joberr.rar_unsupported": "This .rar has duplicate or unsafe file paths, or a feature the uploader can't stream. Extract it on your computer and upload the folder instead.",
"pkg.patch_did_not_apply": "The PS5 accepted this update and then did nothing with it — the game is still on its previous version. This means the console could not match the update to the base game you have installed. Re-install the base game through ps5upload from the base package that goes with this update (choose Override), then apply the update again.",
"pkglib.updateBaseUnknown.title": "This update might not apply",
"pkglib.updateBaseUnknown.installAnyway": "Install anyway",
"pkglib.updateBaseUnknown.body": "{id} is installed, but not from a base package ps5upload installed — so the PS5 may not be able to match this update to it. When that happens the console reports success and silently changes nothing. If the game stays on its old version afterwards, install the matching base package through ps5upload (choose Override), then apply this update again.",
"pkg.reverify_impossible": "The PS5 accepted this install, but ps5upload has nothing to identify the installed package by, so it cannot confirm it. Check the PS5's Notifications for the result. The staged package was kept.",
"pkg.reverify_gave_up": "Still not confirmed after 30 minutes. A very large title can take longer — check the PS5's Notifications, or use Recheck to look again.",
"pkg.patch_regressed": "Re-applying this update removed it — the game has gone back to its base version. The PS5's installer treats a re-applied update as one to undo. Apply the update once more to return to the updated version, and avoid re-installing an update the game already has.",
"sdk_patch_libc": "Also patch libc.prx",
"sdk_patch_libc_hint": "A compatibility edit some backported games need — and that stops others from starting. Leave it off unless the game fails to launch without it.",
backport_action: "Backport",
