job_why_window_full: "Receive window full {pct} %: data was sent faster than the console acknowledged it, while the console reported neither its drive nor its workers as the limit. That usually means a slow network link (Wi-Fi, a weak signal or a busy network); a wired connection is the usual fix.",
install_path_fallback_label: "Install by file path when the PS5 cannot reach this computer",
install_path_fallback_hint: "A last resort for a package that is already on the PS5, when the PS5 refuses it from its own storage and cannot fetch it from this computer either. Only used for a base game that is not installed, so it cannot remove anything. Unproven: it has worked on firmware 11.20 and is refused on 13.60. If you try it, please report whether it worked.",
