"arcpkg.choose": "Choose archive…",
"arcpkg.help": "For a .zip, .7z or .rar that holds one or more .pkg files, in any folder. Only the packages are unpacked, straight to the PS5 (nothing is extracted on this computer), then installed one by one: the base game before its update, then DLC. A multi-part RAR (.part1.rar, .part2.rar…) works: choose the first part and keep the rest beside it. A password is asked for when a RAR needs one; password-protected ZIP and 7z files are not supported.",
"arcpkg.keepsRunning": "This keeps running if you open another screen; it also shows in Tasks.",
"arcpkg.notArchive": "That file is not a .zip, .7z or .rar archive.",
"arcpkg.pick": "Choose an archive",
"arcpkg.title": "Install packages from an archive",
"install.library.title": "Package copies on the PS5",
"install.stream.file.help": "Choose a .pkg or .fpkg, or drop one anywhere on this window. Keep this app open until the install finishes; its progress shows in the queue above and in Tasks.",
"install.stream.file.title": "Install a package file",
"install.tab.stream.lead": "The PS5 installs straight from this computer or from a link. No copy is put on the PS5 first, so it needs no spare space there, and it is the most reliable way to install.",
"install.tab.upload.lead": "The package is copied onto the PS5 first, then installed from that copy. Use this when the PS5 cannot reach this computer (Stream fails with a network error), or to keep packages on the PS5 so you can reinstall them later without this computer.",
"install.upload.file.browser": "Copying a package to the PS5 from here needs the desktop app. In the web UI, use Stream & install, or install packages that are already on the PS5 below.",
"install.upload.file.help": "Choose a .pkg or .fpkg. The copy needs free space on the PS5 for the whole package, and stays in the list below until you remove it.",
"install.upload.file.title": "Copy a package to the PS5 and install it",
"linkcard.confirm.direct": "The PS5 downloads the package from the link by itself and installs it. This computer is not needed once it has started, and progress shows on the PS5 (Downloads), not here. If the PS5 cannot fetch the link, the app streams it through this computer instead. Reinstalling over an installed game may remove it if Sony's installer fails. Use only a package link you trust and are authorized to install.",
"linkcard.confirm.download": "This computer first saves the whole package to its disk, then installs it on the PS5. It must stay awake until both are done and needs free space for the package. Reinstalling over an installed game may remove it if Sony's installer fails. Use only a package link you trust and are authorized to install.",
"linkcard.confirm.stream": "This computer downloads the package and passes it straight to the PS5, so it must stay awake and connected until the install finishes. Nothing is saved to disk. Reinstalling over an installed game may remove it if Sony's installer fails. Use only a package link you trust and are authorized to install.",
"linkcard.confirm.title": "Install from this link?",
"linkcard.fact.awake": "Keep this computer awake",
