"linkcard.fact.progress_here": "Progress shown here",
"linkcard.fact.progress_ps5": "Progress on the PS5",
"linkcard.forget": "Remove from the list",
"linkcard.help": "Paste a direct download link to a .pkg. Nothing is copied to the PS5 first, so a 100 GB game needs no spare space there.",
"linkcard.how": "How should it be fetched?",
"linkcard.insecure": "Skip the certificate check",
"linkcard.insecure_hint": "For your own server, or a site whose certificate is out of date. It applies here because this computer makes the connection.",
"linkcard.install": "Install from link",
"linkcard.mode.direct": "The PS5 downloads it",
"linkcard.mode.direct_body": "The PS5 fetches the link by itself. It must be able to reach the link, and the address must be short (the app shortens a long one, and then has to stay open).",
"linkcard.mode.download": "Download here first, then install",
"linkcard.mode.download_body": "This computer saves the whole package, then installs it. Slowest, but a link that expires or drops part-way only costs a retry of the download.",
"linkcard.mode.stream": "Stream through this computer",
"linkcard.mode.stream_body": "This computer downloads over several connections and passes it straight to the PS5. Usually the fastest, and works when only this computer can reach the link.",
