stop: "Stop",
activity_description_v2: "Everything the app is doing and has done on your consoles: uploads, downloads, installs and file operations. Stop or retry one from here. The last 100 are kept, also after a restart.",
audit_log_description_v3: "A record, kept in this app on this computer, of power actions, deletes, unregisters, uninstalls and installs. The newest 256 are kept and older ones roll off; there is no clear button, but clearing the app's data or browser storage erases it. The last 100 are shown.",
first_run_description_v3: "Loads what most set-ups need, in the right order: kstuff (lets fake packages install and run), ShadowMount+ (puts game images and folders on the PS5's home screen) and ps5upload's own helper. After the PS5 restarts, Connection offers this wizard again.",
fw_spoof_subtitle_v2: "Checks whether the firmware version this PS5 reports has been changed by a spoofing payload, so you know its real version before you install something that depends on it.",
game_activity_subtitle_v3: "What was played on this PS5 and for how long. Tracked play time is counted by the ps5upload helper on the console; Console Play Time is read from the console's own records.",
health_subtitle_v2: "Checks that the PS5, this app and the network between them are working, says what to fix when something is not, and measures how fast files move between them.",
remotePlay_subtitle_v2: "Set this PS5 up for Remote Play and get the PIN that pairs the PS Remote Play app with it.",
saves_description_v2: "Save data on the PS5, one entry per game. Back a game's saves up to a .zip on this computer and restore them later.",
saves_description_browser: "Save data on the PS5, one entry per game. Backing saves up to a .zip and restoring them needs the desktop app; here you can see them and open their folders.",
screenshots_description_v3: "Screenshots saved on the PS5 (its Capture Gallery). Preview them, download them to this computer, or select some to delete them.",
screenshots_description_browser_v2: "Screenshots saved on the PS5 (its Capture Gallery). Download them to a folder on the computer running ps5upload, or select some to delete them.",
shell_description_v2: "Type commands that run on the PS5, in the helper's process. For advanced use. Output is limited to 256 KB per command; the up and down arrows recall earlier commands.",
videos_description_v3: "Video clips saved on the PS5 (its Capture Gallery). Download them to this computer as they are; no conversion is needed. Select some to delete them.",
videos_description_browser_v2: "Video clips saved on the PS5 (its Capture Gallery). Download them as they are to a folder on the computer running ps5upload; no conversion is needed. Select some to delete them.",
"arcpkg.links.go": "Download {count} file(s)",
"arcpkg.links.help": "Paste the direct link to the archive, or to every part of a split one, one per line. The files are downloaded to this computer (Downloads/ps5upload), which needs room for all of them; then the packages inside are unpacked to the PS5 as above.",
"arcpkg.links.kept": "{count} downloaded file(s) are in {dir}. They are kept so the install can be retried; delete them when you are done.",
"arcpkg.links.progress": "Downloading file {n} of {count} to this computer…",
"arcpkg.links.title": "The archive is behind download links",
"arcpkg.noFirstPart": "The files were downloaded, but none of them is the first part of an archive (.zip, .7z, .rar or .part1.rar). Check the links.",
"fpkg.image.done": "Game image written and read back. Copy it to a PS5 drive (Upload) and ShadowMount+ will mount it.",
"fpkg.image.what": "One file you copy to a PS5 drive, which ShadowMount+ mounts and shows on the home screen. Nothing is installed.",
"fpkg.image.folderOnly": "Only a game folder on this computer can become a game image.",
"fpkg.image.folderOnly_v2": "Only a game folder (on this computer, a saved server or the PS5) can become a game image.",
"fpkg.image.folderOnly_v4": "Only a game folder, game image or archive (.zip, .7z, .rar) with a game in it can become a game image; an archive is unpacked into the output folder first.",
"fpkg.card.make": "② What to make",
"fpkg.card.options_v2": "③ Options",
"fpkg.card.run_v2": "④ Build & install",
"fpkg.options.image": "Image",
"fpkg.make.pkg_title": "A package (.pkg)",
"fpkg.make.pkg_body": "Installs on the PS5 like a game from the store, streamed from here or uploaded first. PS4 games play on any firmware; PS5 games on 11.60 and below.",
"fpkg.make.image_title": "A game image",
"fpkg.make.image_body": "One file on a PS5 drive that ShadowMount+ mounts and shows on the home screen. Nothing is installed, and it plays on firmware where a PS5 package will not.",
"fpkg.make.recommended": "Recommended",
"fpkg.make.recommended_fw": "Recommended on FW {fw}",
"fpkg.make.pick_game": "Check a game under ① and the better choice for it on your PS5 is marked.",
"fpkg.make.why_image": "This PS5 game would install as a package but not play on FW {fw}; as an image it does.",
"fpkg.make.why_pkg": "A package is the ordinary choice: it installs and plays like any other game.",
