connection_payload_engine_unreachable: "The app could not reach its own engine on this computer, so it cannot tell whether the helper started on the PS5. This is not a PS5 problem: the notice at the top of the window says why and can restart the engine. Then press Send helper again. ({error})",
"engine_problem.missing.fix": "Restore ps5upload-engine from your antivirus quarantine (or allow it), or reinstall the app.",
"engine_problem.missing.why": "The engine program is missing from the app's folder. Security software sometimes quarantines it.",
"engine_problem.port.fix": "Press Restart engine. If that fails, allow ps5upload-engine in your firewall or antivirus, then restart the app.",
"engine_problem.port.why": "Something holds the engine's address ({url}) but does not answer: another program on that port, or security software blocking connections to it.",
"engine_problem.proxy.fix": "Turn off the proxy or VPN tool for local addresses (127.0.0.1), or start the app without the http_proxy / ALL_PROXY setting.",
"engine_problem.proxy.why": "Requests to the engine went to a proxy set on this computer instead of to the engine.",
"engine_problem.remote.fix": "Check that the engine (Docker container or other computer) is running and reachable at that address, or change it in Settings.",
"engine_problem.remote.why": "The engine this app is set to use ({url}) does not answer.",
"engine_problem.restart": "Restart engine",
"engine_problem.slow.fix": "Press Restart engine. Firewall or antivirus software that filters local connections can cause this too: allow ps5upload-engine.",
"engine_problem.slow.why": "The engine is running but does not answer.",
"engine_problem.stopped.fix": "Press Restart engine. If it stops again, the Logs screen shows why.",
"engine_problem.stopped.why": "The engine is not running: it stopped, or never started.",
"engine_problem.title": "The app cannot reach its engine on this computer",
"engine_problem.web.fix": "Check that the server (Docker container) is running, then reload this page.",
"engine_problem.web.why": "This page lost its connection to the ps5upload server it came from.",
gate_engine_down_body_v2: "This screen needs the app's engine, which is not answering. The notice at the top of the window says why and can restart it.",
"profile.np.body": "Makes the PS5 treat the signed-in account as signed in to PlayStation Network, without contacting Sony. Some console features only open for a signed-in account, Remote Play among them. It uses np-fake-signin by earthonion, fetched from its project page when you press the button.",
"profile.np.browser_v2": "Signing in needs the desktop app: it fetches np-fake-signin and sends it to the PS5, which the web UI cannot do.",
"profile.np.confirm_title": "Sign this account in?",
"profile.np.failed": "Sign-in did not run",
"profile.np.fetching": "Getting np-fake-signin…",
"profile.np.sending": "Sending it to the PS5…",
"profile.np.sent": "np-fake-signin {version} ran on the PS5. Restart the PS5 to finish; the account then shows as signed in, and Settings > System > Remote Play can be turned on.",
"profile.np.sign_in": "Sign in",
"profile.np.state_loading": "Reading the account…",
"profile.np.state_no_slot": "No account above is named {user}, so np-fake-signin would stop. Give the account the same name as the signed-in user, or activate one for it.",
"profile.np.state_no_user": "No user is signed in on the PS5. Sign in to the profile you want, then come back.",
"profile.np.state_not_activated": "{user} (account {slot}) has no account id yet. Activate it under Accounts above first.",
"profile.np.state_ready": "Ready: {user} (account {slot}) is activated.",
"profile.np.step_activate": "The account needs an account id. A PSN-linked account has one; otherwise activate it under Accounts above (offline activation).",
"profile.np.step_run": "Press Sign in with that user signed in on the PS5. It runs once and exits.",
"profile.np.title": "Sign in to PlayStation Network (offline)",
"fpkg.image.compress": "Compress it into a .ffpfsc",
"fpkg.image.exfat_body": "For games that only work like content on an external drive.",
"fpkg.image.exfat_choice": ".exfat",
"fpkg.image.ffpkg": ".ffpkg (UFS2), recommended",
"fpkg.image.ffpkg_body": "What ShadowMount+ recommends for most games.",
"fpkg.image.make": "Make game image",
"fpkg.image.make_compressed": "Make compressed image",
"fpkg.image.compress_body_v2": "Usually 40–60% smaller, slower to make, and always mounted read-only. It is compressed as it is written, so only the compressed file is ever on disk.",
"fpkg.image.level_fast_body": "Quickest to make, a little larger.",
"fpkg.image.level_balanced_body": "Almost as small, and several times faster to make.",
"fpkg.image.level_smallest_body": "Smallest file: a second, stronger encoder runs on every block, so it takes several times as long.",
"fpkg.image.ffpfs": ".ffpfs (PFS), experimental",
"fpkg.image.ffpfs_body": "Experimental in ShadowMount+ 1.7. File names must be plain ASCII; the image's own name is kept to 63 characters.",
"fpkg.image.lz4": "AMPR LZ4 asset packs (smaller, for ShadowMount+)",
"fpkg.image.lz4_body": "Packs the game's data into LZ4 asset packs that the game's own ampr_emu (fakelib/libSceAmpr.sprx) reads back, so the image is smaller. Executables, system files and already-compressed media stay as they are. Plain .exfat only, without .ffpfsc compression.",
"fpkg.image.lz4_unavailable": "Not available for this game: {reason}",
"fpkg.image.lz4_needs_runtime": "Tick “Put ampr_emu 0.4.2.1 into the image” above to use packs: {reason}",
"fpkg.image.lz4_runtime": "The game's ampr_emu: {version}",
"fpkg.image.lz4_profile": "Use a profile (.toml)…",
"fpkg.image.lz4_profile_named": "Profile: {name}",
"fpkg.image.lz4_profile_clear": "Use the built-in profile",
"fpkg.image.lz4_install_runtime": "Put ampr_emu 0.4.2.1 into the image",
"fpkg.image.lz4_install_runtime_body": "{reason}. The image gets drakmor's ampr_emu 0.4.2.1 as fakelib/libSceAmpr.sprx (fetched once from its GitHub release and checked against a known digest); the game's own copy stays beside it as libSceAmpr.sprx.orig.",
"fpkg.image.lz4_no_ampr": "This game does not read its files through AMPR, so nothing in it could serve asset packs. Compress it into a .ffpfsc instead: ShadowMount+ decompresses that for any game.",
"fpkg.image.verify_chunk": "Read-back check, per read",
"fpkg.image.verify_chunk_body": "After writing, the image is read back and checked. 8 MiB was fastest in measurement; try another if your disk disagrees. The check itself is the same at any size.",
"fpkg.image.full_verify": "Full verification",
"fpkg.image.full_verify_body": "Re-reads every byte of the output to check it. Takes longer",
"fpkg.image.verify_chunk_default": "{n} MiB (default)",
"fpkg.image.verify_chunk_mib": "{n} MiB",
