trace_what: "For an LZ4 game image that loads the way the game plays. A measuring build of ampr_emu records every file the game reads while you play; a profile built from those sessions picks block sizes, layouts and cache sizes per file instead of one guess for all. Convert uses it when you make an LZ4 image of this game.",
