"minion_lan_label": "Open Minion from other devices on your network",
"minion_lan_hint": "Off: only the PS5's own browser opens it. On: a phone, tablet or computer on the same network can open it too, so anyone on that network can. Turn it on at home only.",
"minion_open_here": "Open here",
"minion_remove_note": "Remove turns Minion off and deletes what it keeps on the PS5: its Files favourites and recent folders, its game Library cache and its controller log. Network shares, cheats and backups stay; the PC app uses them too.",
"minion_remove": "Remove Minion from this PS5…",
"minion_remove_title": "Remove PS5Upload Minion?",
"minion_remove_confirm": "Its home-screen tile and page go, and its own files on the PS5 are deleted. The helper keeps it off from now on. You can turn it back on here at any time.",
