"connection_send_payload_moved": "Sending another payload (kstuff, etaHEN, any .elf)? That is in Payloads → Send payload. This screen sends only the PS5Upload helper.",
"connection_send_payload_open": "Open Send payload",
"upload_elf_title": "This is a payload (.elf), not a game",
"upload_elf_body": "Uploading it only copies the file. ShadowMount+ picks up game folders (with eboot.bin and sce_sys) and game images, never an .elf, so it will not appear on the home screen. To run it, send it to the console's loader instead. A homebrew app that comes as a .ffpkg or .exfat image, or as a folder with eboot.bin, is what to upload.",
"netdoctor.hint.below_test": "This upload runs at {speed}, well below the {expected} the speed test measured.",
"netdoctor.hint.runs_at": "This upload runs at {speed}.",
"netdoctor.hint.cause_source": "Reading the files on this computer is what holds it back, not the network: a USB or hard drive, a network share (NAS) or unpacking an archive is slower than the link. Copying the game to an internal SSD first, or uploading an archive's files once unpacked, gives full speed.",
"netdoctor.hint.cause_disk": "The PS5's drive is what holds it back, not the network: an external USB drive, a nearly full drive or thousands of small files (each costs time of its own) write slower than the link delivers. A game image (.ffpkg or .exfat) goes as one file.",
"netdoctor.hint.cause_workers": "The PS5 is still writing what it received, not waiting on the network. With many small files each one costs time of its own; a game image (.ffpkg or .exfat) goes as one file.",
"netdoctor.hint.cause_cap": "The upload speed limit (about {cap} MiB/s, on this screen and in Settings) is what holds it back. Set it to 0 to remove it.",
"profile.np.confirm_body_v2": "np-fake-signin writes PlayStation Network sign-in files and settings for {user} on the PS5. Nothing is sent to Sony. Restart the PS5 afterwards.",
"profile.np.side_effect": "Known side effect: afterwards some consoles ask to \"Temporarily Disable PS5 Console Restrictions\" before any game opens, and Settings > Users and Accounts > Other > Sign out can stay greyed out. The app first keeps a copy of everything np-fake-signin changes on the PS5, so Undo sign-in here puts it back.",
"profile.np.backing_up": "Keeping a copy of the account's current settings on the PS5…",
"profile.np.backup_failed": "The PS5 could not keep a copy of the account's settings, so np-fake-signin was not run. Replace the helper with this app's version and try again. ({error})",
"profile.np.step_restart_v2": "Restart the PS5. To undo it later, press Undo sign-in here and restart again.",
"profile.np.undo": "Undo sign-in",
"profile.np.undo_hint": "A copy of this account's settings from before the sign-in is kept on the PS5; this puts it back.",
"profile.np.undo_confirm_title": "Undo the sign-in?",
"profile.np.undo_confirm_body": "Puts {user}'s settings and files back as they were before np-fake-signin ran. Restart the PS5 afterwards. Features that need a signed-in account, Remote Play among them, may stop opening until you sign in again.",
"profile.np.undoing": "Putting the settings back…",
"profile.np.undone": "Put back ({count} settings and files). Restart the PS5 to finish.",
"profile.np.no_backup": "This account carries np-fake-signin's template settings (birth date 1983-04-12, the offline-adult flag off), and no copy from before is kept on this PS5, so the app cannot undo it. If the PS5 now asks to temporarily disable console restrictions before games open: Settings > Family and Parental Controls > PS5 Console Restrictions (passcode 0000 unless you changed it), and lift the restrictions there.",
"linkdl.lz4_title": "This link is LZ4-compressed",
"linkdl.image_title": "This link is a game image",
"linkdl.lz4_help": "ps5upload can unpack it while it downloads, so the PS5 receives the unpacked file. Nothing is stored on this computer, and the PS5 only needs room for the unpacked file.",
"linkdl.lz4_unpack": "Unpack on the way",
"linkdl.lz4_unpack_hint": "Off: the .lz4 file is saved on the PS5 as it is.",
"linkdl.image_hint": "Game image ({kind}). ShadowMount+ mounts it as it is from a folder it scans, such as homebrew on a drive. The file appears there only once it is complete.",
"pm_add_failed": "Couldn't store {name} in Payload Manager",
"pm_catalogue_match": "Catalogue: {name}",
"pm_replace_tooltip": "Payload Manager keeps no version for a payload stored by hand, so ps5upload cannot tell whether this one is older. Replacing stores the catalogue's release in its place, keeping its place in the boot list; after that, updates are offered here.",
"pm_replace_with": "Replace with {tag}",
