"accounts_title": "Accounts",
"accounts_users_title": "Users",
"ps4move_title": "Move saves from a PS4",
"ps4move_badge": "Experimental",
"ps4move_experimental": "Experimental: putting PS4-format saves back on a PS5 has mixed reports, and a game may not load one. Try one game first; its PS5 save is kept, so you can put it back from the game's save backups.",
"ps4move_safety": "The PS4 is only read, never changed. Its saves are copied to this computer first. On the PS5 only the games you pick are touched, each one's own save is backed up before it is replaced, and nothing else (users, system files, trophies) is changed.",
"ps4move_need_dir": "Choose a folder in Automatic backups above first: the PS4's saves are kept there, and so is each PS5 save before it is replaced.",
