"rp_setup_guide": "Setup guide",
"rpg_user_title": "Sign in to a user on the PS5",
"rpg_user_body": "On the console, pick the user you will play as. Nobody has to stay on screen, but the user must be signed in. Use a user without a login passcode: a passcode stops the automatic sign-in when the console wakes.",
"rpg_account_title": "Give that user an account ID",
"rpg_account_body": "Remote Play pairs with an account ID. A user linked to PlayStation Network already has one; an offline user needs one set in Users above (any ID works; write it down, saves made afterwards are tied to it).",
"rpg_signin_title": "Sign the account in to PlayStation Network (offline)",
"rpg_signin_body": "The PS5 only lets a signed-in account use Remote Play. If the console's own Remote Play setting is greyed out, run the offline sign-in below (nothing is sent to Sony), then restart the PS5. It can be undone.",
"rpg_signin_fix": "Go to sign-in",
"rpg_service_title": "Turn Remote Play on",
"rpg_service_body": "Settings › System › Remote Play › Enable Remote Play. The app can switch it on for you, and on firmware 10.00 and later also allow it for this user.",
"rpg_rest_title": "Let the PS5 be woken from rest mode",
"rpg_rest_body": "Settings › System › Power Saving › Features Available in Rest Mode: turn on Stay Connected to the Internet and Enable Turning On PS5 from Network. Without them, a console in rest mode cannot be woken and its network sleeps after a few seconds. Only the console can show these.",
"rpg_pair_title": "Pair this app with the console",
"rpg_pair_body": "Connection › Wake & sign in › Set up. One click registers this app with the PS5 (like pairing the PS Remote Play app) and keeps its keys on this computer. Streaming, waking and signing in all use them; do it again after resetting the console or changing the user.",
"rpg_play_title": "Play",
"rpg_play_body": "Open Remote Play and press Start: the app wakes the console if it is resting, signs in, and streams. Play with a controller connected to this computer, the keyboard, or touch. To use Sony's PS Remote Play app or chiaki-ng instead, request a PIN below and enter it there.",
"rpg_play_fix": "Open Remote Play",
"rpg_title": "Set up Remote Play",
"rpg_progress": "{done} of {n} checked steps done",
"rpg_on_console": "check on the console",
"rpg_trouble": "If it still does not work",
"rpg_t_start_q": "Start is greyed out on the Remote Play screen.",
"rpg_t_start_a": "This app is not paired with that console yet: do step 6 (Connection › Wake & sign in › Set up).",
"rpg_t_pair_q": "Setting up pairing says there is no signed-in user with an activated account.",
"rpg_t_pair_a": "Steps 1 and 2: sign in to a user on the PS5 and give it an account ID, then try again.",
"rpg_t_grey_q": "The PS5's own Remote Play setting is greyed out.",
"rpg_t_grey_a": "The account is not signed in to PlayStation Network. Run the offline sign-in (step 3) and restart the PS5.",
"rpg_t_wake_q": "The console does not wake, or wakes but stays on the user screen.",
"rpg_t_wake_a": "Check step 5 on the console. A user with a login passcode stops the automatic sign-in. If the console was reset or the user changed, set up pairing again (step 6).",
"rpg_t_black_q": "The picture stays black, stutters, or the sound crackles.",
"rpg_t_black_a": "Use a wired connection or 5 GHz Wi-Fi for the PS5 and this computer, and try 720p or 30 fps in Remote Play's settings. A firewall on this computer must allow the app on the local network (Remote Play uses TCP and UDP ports 9295–9304). In a browser, use a current Chrome, Edge or Safari: the picture needs WebCodecs.",
"rpg_t_busy_q": "It says the PS5 is still finishing the last session, or another console is streaming.",
"rpg_t_busy_a": "One console streams at a time and the PS5 needs up to 30 seconds after a session ends. Stop the other stream, wait a moment, then press Start again.",
"rpg_t_restrict_q": "After the offline sign-in, games ask to disable console restrictions.",
"rpg_t_restrict_a": "Use Undo sign-in on this page and restart, or lift the restriction in Settings › Family and Parental Controls › PS5 Console Restrictions (passcode 0000 unless you changed it).",
"rp_switch_start": "Stop the other stream and start",
"rp_streaming_other": "Remote Play is streaming {name}",
"rp_show_it": "Show it",
"rp_streaming_other_body": "One console streams at a time. It keeps playing while you look at this one; Start here stops it first.",
"rp_moved": "Playing in another window.",
"rp_play_here": "Play here",
"rp_show_stats_short": "Stats",
"rp_unmute": "Sound on",
"rp_mute": "Mute",
"rp_exit_fullscreen": "Leave full screen",
"rp_other_device_playing": "{name} is using Remote Play on this console",
"rp_other_device_playing_body": "A PS5 plays Remote Play with one device at a time: starting here ends it there.",
"mesh_rp_started": "{name} started Remote Play on this console",
"rp_keys_body3": "Click the picture to play with the keyboard; Esc gives the pointer back. Double-click for full screen; there a quick Esc is Circle and holding Esc leaves full screen. Keys, sound and more are in Settings.",
