"send_title_v2": "Upload & Install",
"collection.send_many_body_v2": "Each PS5 gets what it lacks: the game's package, or its folder, image or archive, plus newer updates and DLC for the games it has. Packages stream from this computer; the rest uploads to the drive set in Upload & Install, in the homebrew folder.",
"first_run_step4_body_v3": "Drop a USB stick into your PS5 with .ffpkg game images and ShadowMount+ will auto-mount them — they'll appear in Games. To send other files or install .pkg packages, use Upload & Install.",
"first_run_go_upload_v2": "Open Upload & Install",
"fpkg.aboutFake_v2": "The result is a fake package, so the console needs fake-package support loaded before it will install: kstuff (the build with PS5 fake-package support), a53_ppr_install_fast.elf and shadowmountplus.elf, in that order. Upload & Install says the same next to its install buttons.",
"fpkg.openUpload_v2": "Open Upload & Install",
"connection_step3_hint_v3": "Open Upload & Install and drop in a game folder, a .exfat or .ffpkg image, or a .pkg package. Images and folders you send are listed in the game's page in Games, where Mount puts them on the PS5's home screen.",
"connection_go_upload_v2": "Open Upload & Install",
"netdoctor.speed_cap.on.fix_v2": "Remove the limit in Upload & Install if you don't need it.",
"payloads_fpkg_ppr_note_v2": "Installing fake packages also needs a53_ppr_install_fast.elf, which is not in this list: no download is published for it, and it is built from the source on GitHub. Upload & Install lists everything fake packages need, in order.",
"fs_extract_next_pkgs_v2": "It holds {n} package(s): install them from Upload & Install, or from their row here.",
"game_hub_no_addons_v2": "No DLC packages staged for this title. Send one from Upload & Install.",
"game_hub_open_install_v2": "Open Upload & Install",
"bandwidth_cap_off_hint_v3": "No limit. Set one if uploads saturate your Wi-Fi/LAN and make other devices lag. It applies to every upload, from Upload & Install, the queue and Files, from the next one started.",
"queue_links_cleared_body_v2": "{n} install link(s) weren't kept after restart — links are never saved to disk. Add them again from Upload & Install.",
"game_hub_no_updates_v2": "No update packages staged for this title. Send one from Upload & Install.",
"pkglib.fpkgsupport.firmware": "PS5 fake packages (PS5 FPKG) are not supported yet on firmware later than 11.60: they install, but the game does not start. PS4 fake packages are fine.",
"upload_drop_here3": "Drop or choose packages, games, disk images, archives or any file",
"upload_pick_here_mobile3": "Choose packages, games, disk images, archives or any file",
"upload_drop_kind_pkg": "Packages (.pkg, .fpkg): installed as a game, update or DLC, streamed from here or uploaded first.",
"upload_drop_kind_game": "Game folders and game dumps: copied to the PS5; they can go on the home screen.",
"upload_drop_kind_image": "Disk images (.exfat, .ffpkg, .ffpfs, .ffpfsc): copied to the PS5; they can be mounted.",
"upload_drop_kind_archive": "Archives (.zip, .7z, .rar): extracted onto the PS5.",
"upload_drop_kind_other": "Any other file or folder: copied as it is.",
"upload_other_ways": "Or install a package:",
"queue_stream_fail_hint": "Stream & install has the PS5 fetch the package from this computer. If it keeps failing, allow ps5upload through this computer's firewall on the local network so the PS5 can reach it, or use Retry via upload, which copies the package to the PS5 first and then installs it.",
"err_install_enoent_generic_v2": "Sony's installer couldn't open a file it needed during install (kernel error 0x80020002 = ENOENT). If this is a DLC pkg, the base game isn't installed yet — install the base first. Otherwise the staged package may have been deleted between upload and install; retry the install once. If it keeps failing, install it with Stream & install in Upload & Install, which sends the package straight from this computer instead of copying it to the console first.",
"upload_convert_first": "Convert first",
"batch_convert_first_hint": "Open the ticked games, folders and images in Workshop, to make packages, images or folders of them first",
"add_sources_pick_folders": "Choose one or more folders",
"add_sources_pick_files": "Choose one or more files",
"workshop_add_locked": "A game is being made: games picked now wait in the queue.",
"workshop_add_hint": "Pick one game to check it here. Several games, or a folder of games, go into the queue and are made one after another.",
"workshop_description_v2": "Change a game's format before it goes to the PS5: make a package (.pkg), a game image (.exfat, .ffpkg, or the smaller .ffpfsc) or a plain folder, or look inside an image or package and change its files. The work runs on this computer. To send a game as it is, use {send}.",
"cq_title_v2": "⑤ Queue",
"cq_about": "Made one after another on this computer, each as ②, ③ and ④ were set when it was added. Add more under ①, even while the queue runs; change a waiting game with its options button.",
"cq_then_send": "A game set to install or upload goes on to {send}'s queue once it is made.",
"cq_open_send": "Open {send}",
